head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf05004";
scwin.call_magnt_tp_cd = null;
scwin.put_magnt_tp_cd = null;
scwin.call_rownum = 0;
scwin.put_rownum = 0;
scwin.result = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — imbdoptCorpbndCd, imbdopt_corpbnd_cd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.call_magnt_tp_cd = $c.util.getComponent('call_magnt_tp_cd');
        scwin.put_magnt_tp_cd = $c.util.getComponent('put_magnt_tp_cd');
        scwin.init_conds();
        scwin.init_datefmt_cal_fstCallExerDd();
        scwin.init_datefmt_cal_callExerStrtDd1();
        scwin.init_datefmt_cal_fstPutExerDd();
        scwin.init_datefmt_cal_putExerStrtDd1();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf05004.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_imbdoptCorpbndCd", fn: function(){ return ((dma_pageContext.get("imbdoptCorpbndCd") ?? "") === 1 || (dma_pageContext.get("imbdoptCorpbndCd") ?? "") === 3); } }, { id: "if_imbdoptCorpbndCd_2", fn: function(){ return ((dma_pageContext.get("imbdoptCorpbndCd") ?? "") === 2 || (dma_pageContext.get("imbdoptCorpbndCd") ?? "") === 3); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_datefmt_cal_fstCallExerDd
 * @description 초기화 — datefmt cal fst Call Exer Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_fstCallExerDd = function () { $c.date.checkCalendarFormat("cal_fstCallExerDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_callExerStrtDd1
 * @description 초기화 — datefmt cal call Exer Strt Dd1
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_callExerStrtDd1 = function () { $c.date.checkCalendarFormat("cal_callExerStrtDd1", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_fstPutExerDd
 * @description 초기화 — datefmt cal fst Put Exer Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_fstPutExerDd = function () { $c.date.checkCalendarFormat("cal_fstPutExerDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_putExerStrtDd1
 * @description 초기화 — datefmt cal put Exer Strt Dd1
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_putExerStrtDd1 = function () { $c.date.checkCalendarFormat("cal_putExerStrtDd1", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {

        // imbdopt_corpbnd_cd ->     1=call, 2=put, 3=call&put
        // 초기 rownum 셋팅
        if((String(((dma_pageContext.get("imbdopt_corpbnd_cd") ?? "")) == null ? '' : ((dma_pageContext.get("imbdopt_corpbnd_cd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("imbdopt_corpbnd_cd") ?? "")) == null ? '' : ((dma_pageContext.get("imbdopt_corpbnd_cd") ?? "")))) === 1){
            scwin.call_rownum = 1;
        }else if((String(((dma_pageContext.get("imbdopt_corpbnd_cd") ?? "")) == null ? '' : ((dma_pageContext.get("imbdopt_corpbnd_cd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("imbdopt_corpbnd_cd") ?? "")) == null ? '' : ((dma_pageContext.get("imbdopt_corpbnd_cd") ?? "")))) === 2){
            scwin.put_rownum = 1;
        }else if((String(((dma_pageContext.get("imbdopt_corpbnd_cd") ?? "")) == null ? '' : ((dma_pageContext.get("imbdopt_corpbnd_cd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("imbdopt_corpbnd_cd") ?? "")) == null ? '' : ((dma_pageContext.get("imbdopt_corpbnd_cd") ?? "")))) === 3){
            scwin.call_rownum = 1;
            scwin.put_rownum = 1;
        }

        // 부모창에 저장된 인풋값의 갯수만큼 이자율변경 입력박스 생성
        scwin.makeInputFromParent((String(((dma_pageContext.get("imbdopt_corpbnd_cd") ?? "")) == null ? '' : ((dma_pageContext.get("imbdopt_corpbnd_cd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("imbdopt_corpbnd_cd") ?? "")) == null ? '' : ((dma_pageContext.get("imbdopt_corpbnd_cd") ?? "")))));

        /*달력셋팅*/

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05004.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

