 * @returns {void}
 * @hidden N
 */
scwin.cal_offMask = function () { /* 등가 no-op — to-be 필드 마스크 미사용 */ };

/**
 * @method
 * @name chkDate
 * @description chk Date 처리
 * @returns {void}
 * @hidden N
 */
scwin.chkDate = function () { /* 등가 no-op — 날짜 형식은 inputCalendar·제출 검증 몫 */ };

/**
 * @method
 * @name addRow
 * @description add Row 처리
 * @param {*} id id
 * @returns {void}
 * @hidden N
 */
scwin.addRow = function (id) {
    const fm = (document.InputForm || { elements: [] });
    let rownum = 0;
    let rowPlus = null;
    if (id === "Call") {
        rownum = scwin.call_rownum;
        rowPlus = $c.util.getComponent("tbl_call");
    } else {
        if (id === "Put") {
            rownum = scwin.put_rownum;
            rowPlus = $c.util.getComponent("tbl_put");
        }
    }
    let tr;
    let th;
    let td;
    const newRowNum = rownum + 1;
    const $tblCall = $('#tbl_call');
    const $tblPut = $('#tbl_put');
    const $tr = $("<tr></tr>");
    const $td1 = $("<td>" + newRowNum + "차</td>").addClass('first txc');
    let $td2 = null;
    if (id === "Call") {
        $td2 = $("<td><div style=\"display:flex; align-items:center;\"><input type=\"text\" id=\"call_exer_strt_dd_" + newRowNum + "\" name=\"call_exer_strt_dd_" + newRowNum + "\" value=\"\" maxlength=8 class=\"txt input-calendar\" style=\"height: 24px;\" title=\"날짜입력\" onBlur=\"Chk_Date2( this,'행사일 " + newRowNum + "차' )\" onfocus=\"cal_offMask('document.InputForm.call_exer_strt_dd_" + newRowNum + "')\" onkeyup=\"chkDate('document.InputForm.call_exer_strt_dd_" + newRowNum + "')\" /></div></td>");
    } else {
        if (id === "Put") {
            $td2 = $("<td><div style=\"display:flex; align-items:center;\"><input type=\"text\" id=\"put_exer_strt_dd_" + newRowNum + "\" name=\"put_exer_strt_dd_" + newRowNum + "\" value=\"\" maxlength=8 class=\"txt input-calendar\" style=\"height: 24px;\" title=\"날짜입력\" onBlur=\"Chk_Date2( this,'행사일 " + newRowNum + "차' )\" onfocus=\"cal_offMask('document.InputForm.put_exer_strt_dd_" + newRowNum + "')\" onkeyup=\"chkDate('document.InputForm.put_exer_strt_dd_" + newRowNum + "')\" /></div></td>");
        }
    }
    $tr.append($td1);
    $tr.append($td2);
    if (id === "Call") {
        $tblCall.append($tr);
    } else {
        if (id === "Put") {
            $tblPut.append($tr);
        }
    }
    rownum++;
    if (id === "Call") {
        scwin.call_rownum = rownum;
        $("#call_exer_strt_dd_" + newRowNum).datepicker(myDateOpts);
    } else {
        if (id === "Put") {
            scwin.put_rownum = rownum;
            $("#put_exer_strt_dd_" + newRowNum).datepicker(myDateOpts);
        }
    }
};

/**
 * @method
 * @name delRow
 * @description del Row 처리
 * @param {*} id id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delRow = async function (id) {
    let rownum = 0;
    let rowPlus;
    if (id === "Call") {
        rownum = scwin.call_rownum;
        rowPlus = $c.util.getComponent("tbl_call");
    } else {
        if (id === "Put") {
            rownum = scwin.put_rownum;
            rowPlus = $c.util.getComponent("tbl_put");
        }
    }
    const rowCnt = rownum;
    if (rownum > 0) {
        const no = rowPlus.rows.length - 1;
        rowPlus.deleteRow(no);
        rownum--;
    } else {
        if (rownum < 1) {
            await $c.win.alert("삭제 할 행이 없습니다.");
        }
    }
    if (id === "Call") {
        scwin.call_rownum = rownum;
    } else {
        if (id === "Put") {
            scwin.put_rownum = rownum;
        }
    }
};

/**
 * @method
 * @name makeInputFromParent
 * @description make Input From Parent 처리
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.makeInputFromParent = function (index) {

    const parentfm = ((scwin.openerScwin())["SendForm"] !== undefined ? (scwin.openerScwin())["SendForm"] : undefined);
    const fm = (document.InputForm || { elements: [] });
    if (parentfm.call_count.value === '') {
        scwin.call_rownum = 0;
    } else {
        scwin.call_rownum = parseInt(parentfm.call_count.value);
    }
    if (parentfm.put_count.value === '') {
        scwin.put_rownum = 0;
    } else {
        scwin.put_rownum = parseInt(parentfm.put_count.value);
    }
    if (index === 1 || index === 3) {
        let calltemprow = 0;
        if (scwin.call_rownum > 0) {
            calltemprow = scwin.call_rownum;
            $("#tbl_call tr").remove();
            scwin.call_rownum = 0;
            for (let i = 1; i < calltemprow + 1; i++) {
                scwin.addRow('Call');
                if (calltemprow === 1) {
                    $c.util.getComponent("fm.call_exer_strt_dd_" + i).setValue(eval("parentfm.call_exer_strt_dd.value"));
                } else {
                    if (calltemprow > 1) {
                        $c.util.getComponent("fm.call_exer_strt_dd_" + i).setValue(eval("parentfm.call_exer_strt_dd[" + (i - 1) + "].value"));
                    }
                }
            }
        } else {
            scwin.call_rownum = 1;
        }
        if (parentfm.call_magnt_tp_cd.value === '1') {
            /* 수동 전환 필요: call_magnt_tp_cd[0] 선택 — 옵션표 미해결 */ void 0;
        } else {
            if (parentfm.call_magnt_tp_cd.value === '2') {
                /* 수동 전환 필요: call_magnt_tp_cd[1] 선택 — 옵션표 미해결 */ void 0;
            }
        }
        $c.util.getComponent("ipt_callExerRsn").setValue(parentfm.call_exer_rsn.value);
        $c.util.getComponent("cal_fstCallExerDd").setValue(parentfm.fst_call_exer_dd.value);
        const v_str1 = parentfm.call_mmend_tp_cd.value;
        if (v_str1 === '1') {
            /* 수동 전환 필요: call_mmend_tp_cd[0] 선택 — 옵션표 미해결 */ void 0;
        } else {
            if (v_str1 === '2') {
                /* 수동 전환 필요: call_mmend_tp_cd[1] 선택 — 옵션표 미해결 */ void 0;
            }
        }
        $c.util.getComponent("ipt_callExerCycle").setValue(parentfm.call_exer_cycle.value);
        $c.util.getComponent("ipt_callExerCnt").setValue(parentfm.call_exer_cnt.value);
    }
    if (index === 2 || index === 3) {
        let puttemprow = 0;
        if (scwin.put_rownum > 0) {
            puttemprow = scwin.put_rownum;
            $("#tbl_put tr").remove();
            scwin.put_rownum = 0;
            for (let i = 1; i < puttemprow + 1; i++) {
                scwin.addRow('Put');
                if (puttemprow === 1) {
                    $c.util.getComponent("fm.put_exer_strt_dd_" + i).setValue(eval("parentfm.put_exer_strt_dd.value"));
                } else {
                    if (puttemprow > 1) {
                        $c.util.getComponent("fm.put_exer_strt_dd_" + i).setValue(eval("parentfm.put_exer_strt_dd[" + (i - 1) + "].value"));
                    }
                }
            }
        } else {
            scwin.put_rownum = 1;
        }
        if (parentfm.put_magnt_tp_cd.value === '1') {
            /* 수동 전환 필요: put_magnt_tp_cd[0] 선택 — 옵션표 미해결 */ void 0;
        } else {
            if (parentfm.put_magnt_tp_cd.value === '2') {
                /* 수동 전환 필요: put_magnt_tp_cd[1] 선택 — 옵션표 미해결 */ void 0;
            }
        }
        $c.util.getComponent("ipt_putExerRsn").setValue(parentfm.put_exer_rsn.value);
